1	/**
2	 * ============================================================================
3	 * HILO AVIATION - Parts Inventory Routes (M-02)
4	 * ============================================================================
5	 *
6	 * Endpoints:
7	 *   GET   /parts                       — list parts catalog for an org
8	 *   POST  /parts                       — add a new part to the catalog
9	 *   GET   /parts/:id                   — get single part with detail
10	 *   PATCH /parts/:id                   — update a part's catalog fields
11	 *   GET   /parts/:id/transactions      — paginated ledger with running balance
12	 *   POST  /parts/:id/transactions      — record a stock movement
13	 *
14	 * ============================================================================
15	 */
16	
17	import { aiGateway } from '@/lib/ai-control-center';
18	import { db } from '@/lib/db';
19	import * as schema from '@/lib/schema';
20	import { ensureOrgScope, ensureWorkOrderScope } from '@/server/helpers';
21	import type { AuthUser } from '@/server/middleware/auth';
22	import { requireAuth } from '@/server/middleware/auth';
23	import { recordAiTokenUsage } from '@/server/routes/routes-integration-usage';
24	import { and, desc, eq, ilike, or, sql } from 'drizzle-orm';
25	import { Hono } from 'hono';
26	
27	export const partsRouter = new Hono<{ Variables: { authUser?: AuthUser } }>();
28	
29	// ─── Constants ────────────────────────────────────────────────────────────────
30	
31	const VALID_CATEGORIES = new Set([
32	  'engine',
33	  'airframe',
34	  'avionics',
35	  'consumable',
36	  'hardware',
37	  'safety_equipment',
38	]);
39	
40	const VALID_TRANSACTION_TYPES = new Set([
41	  'purchase_receipt',
42	  'wo_issue',
43	  'wo_return',
44	  'adjustment_add',
45	  'adjustment_remove',
46	  'transfer_out',
47	  'transfer_in',
48	  'core_return',
49	  // Legacy values from earlier schema (keep accepting for backward compatibility)
50	  'received',
51	  'issued',
52	  'returned',
53	  'adjusted',
54	]);
55	
56	// ─── Helpers ─────────────────────────────────────────────────────────────────
57	
58	function deriveStatus(
59	  qtyAvailable: number,
60	  reorderPoint: number | null,
61	  shelfLifeExpiry: Date | null,
62	): string {
63	  if (qtyAvailable <= 0) return 'out_of_stock';
64	
65	  if (shelfLifeExpiry) {
66	    const daysUntilExpiry =
67	      (shelfLifeExpiry.getTime() - Date.now()) / (1000 * 60 * 60 * 24);
68	    if (daysUntilExpiry <= 30) return 'expiring_soon';
69	    if (daysUntilExpiry < 0) return 'expired';
70	  }
71	
72	  if (reorderPoint !== null && qtyAvailable <= reorderPoint) {
73	    return 'low_stock';
74	  }
75	
76	  return 'in_stock';
77	}
78	
79	function safeErrorMessage(err: unknown): string {
80	  return err instanceof Error
81	    ? err.message
82	    : typeof err === 'object' && err !== null
83	      ? JSON.stringify(err)
84	      : String(err);
85	}
86	
87	// ─── GET /parts ───────────────────────────────────────────────────────────────
88	
89	partsRouter.get('/parts', requireAuth(), async (c) => {
90	  const { orgId, status, q, locationId, category } = c.req.query();
91	
92	  if (!orgId) {
93	    return c.json({ error: 'orgId is required' }, 400);
94	  }
95	  const denied = await ensureOrgScope(c, orgId);
96	  if (denied) return denied;
97	
98	  try {
99	    const conditions = [eq(schema.partsCatalog.flightSchoolId, orgId)];
100	
101	    if (locationId) {
102	      conditions.push(eq(schema.partsCatalog.locationId, locationId));
103	    }
104	    if (category && VALID_CATEGORIES.has(category)) {
105	      conditions.push(eq(schema.partsCatalog.category, category));
106	    }
107	    if (q) {
108	      conditions.push(
109	        or(
110	          ilike(schema.partsCatalog.partNumber, `%${q}%`),
111	          ilike(schema.partsCatalog.description, `%${q}%`),
112	          ilike(schema.partsCatalog.name, `%${q}%`),
113	        ) as ReturnType<typeof eq>,
114	      );
115	    }
116	
117	    const rows = await db
118	      .select()
119	      .from(schema.partsCatalog)
120	      .where(and(...conditions))
121	      .orderBy(schema.partsCatalog.partNumber)
122	      .limit(500);
123	
124	    const parts = rows.map((p) => {
125	      const qtyAvailable = p.qtyOnHand - p.qtyReserved;
126	      const computedStatus = deriveStatus(
127	        qtyAvailable,
128	        p.reorderPoint,
129	        p.shelfLifeExpiry,
130	      );
131	
132	      return {
133	        ...p,
134	        qtyAvailable,
135	        unitCost: p.unitCost !== null ? Number(p.unitCost) : null,
136	        status: computedStatus,
137	      };
138	    });
139	
140	    // Filter by status after derivation
141	    const filtered =
142	      status && status !== 'all'
143	        ? parts.filter((p) => p.status === status)
144	        : parts;
145	
146	    // Build summary
147	    const summary = {
148	      in_stock: parts.filter((p) => p.status === 'in_stock').length,
149	      low_stock: parts.filter((p) => p.status === 'low_stock').length,
150	      out_of_stock: parts.filter((p) => p.status === 'out_of_stock').length,
151	      expiring_soon: parts.filter((p) => p.status === 'expiring_soon').length,
152	      expired: parts.filter((p) => p.status === 'expired').length,
153	    };
154	
155	    return c.json({ parts: filtered, summary });
156	  } catch (err) {
157	    console.error('[parts GET /] Error:', safeErrorMessage(err));
158	    return c.json({ error: 'Failed to fetch parts' }, 500);
159	  }
160	});
